"""Position-by-position word grammars: a skip-HMM slot grammar and a prefix-core-suffix model.

Stage 6 (intra-word structure) of docs/WORKFLOW.md. Nothing here decodes anything. The point is
to measure *how much of the word-level structure of a text is explained by a small positional
grammar* and to run the identical measurement on controls.

**Slot grammar** (``SlotGrammar``): ``K`` ordered slots; a word is generated by passing the slots
left to right, each slot either skipped (prob ``1 - e_k``) or emitting exactly one unit from its own
distribution ``P(u | k)``. A unit may be allowed in several slots (so ``ee`` or ``ol-ol`` are
possible). This is the unsupervised, probabilistic version of the slot / "crust-mantle-core"
descriptions of Voynichese by Stolfi and Zattera; slots are *learned* by EM (forward-backward over
the alignments of the units to the slots), not written down by hand. The word probability is the
sum over all alignments, so the model is a proper (sub-)distribution over unit strings of length
<= K.

**Prefix-core-suffix** (``AffixModel``): word = prefix + core + suffix with prefixes and suffixes
drawn from small learned sets (possibly empty); a Morfessor-lite hard-EM that segments every
type into its most probable split.

Everything is label-free (it works on any list of unit tuples) so the same code runs on MS 408
(collapsed EVA units) and on single-character controls.
"""
from __future__ import annotations

import math
from collections import Counter, defaultdict
from typing import Hashable, Iterable, Sequence

import numpy as np

LOG2 = math.log(2.0)
UNK = "<unk>"


# ----------------------------------------------------------------------------- helpers

def _group_by_length(words: Sequence[tuple], idx: dict) -> dict[int, tuple[np.ndarray, np.ndarray]]:
    """length -> (positions in ``words``, int matrix (n, L)) with unit indices (unknown -> len(idx))."""
    unk = len(idx)
    by: dict[int, list[int]] = defaultdict(list)
    for i, w in enumerate(words):
        by[len(w)].append(i)
    out = {}
    for L, ids in by.items():
        U = np.array([[idx.get(u, unk) for u in words[i]] for i in ids], dtype=np.int64).reshape(len(ids), L)
        out[L] = (np.array(ids), U)
    return out


def word_counts(words: Iterable[tuple]) -> Counter:
    return Counter(tuple(w) for w in words)


def shuffle_within_words(words: Sequence[tuple], rng) -> list[tuple]:
    out = []
    for w in words:
        l = list(w)
        rng.shuffle(l)
        out.append(tuple(l))
    return out


# ----------------------------------------------------------------------------- slot grammar

class SlotGrammar:
    """Skip-HMM slot grammar with ``K`` slots, fitted by EM (see module docstring)."""

    def __init__(self, K: int = 12, floor: float = 0.02, prune: float = 0.002, min_emit: float = 0.005):
        self.K, self.floor, self.prune, self.min_emit = K, floor, prune, min_emit
        self.units: list = []
        self.idx: dict = {}
        self.P: np.ndarray | None = None      # (K, A) unit distribution per slot
        self.e: np.ndarray | None = None      # (K,) emission probability per slot
        self.loglik_train = float("nan")
        self.iterations = 0

    # ---- fitting
    def fit(self, counts: dict[tuple, float], iters: int = 30, restarts: int = 1, seed: int = 0, tol: float = 1e-4):
        """Fit on weighted word types (``counts``: word tuple -> weight). Words longer than K are ignored."""
        K = self.K
        words = [w for w in counts if 0 < len(w) <= K]
        wts = np.array([counts[w] for w in words], dtype=float)
        self.units = sorted({u for w in words for u in w}, key=str)
        self.idx = {u: i for i, u in enumerate(self.units)}
        A = len(self.units)
        groups = _group_by_length(words, self.idx)
        wsum = wts.sum()
        # relative position of every unit (for the initial slot assignment)
        rel = np.zeros(A)
        cnt = np.zeros(A)
        for i, w in enumerate(words):
            L = len(w)
            for j, u in enumerate(w):
                rel[self.idx[u]] += wts[i] * (j / (L - 1) if L > 1 else 0.5)
                cnt[self.idx[u]] += wts[i]
        rel /= np.maximum(cnt, 1e-9)
        best = None
        for r in range(restarts):
            rng = np.random.default_rng(seed + 7 * r)
            slot_pos = np.arange(K)[:, None]
            sigma = 1.2 + 0.6 * rng.random()
            P = np.exp(-((rel[None, :] * (K - 1) - slot_pos) ** 2) / (2 * sigma ** 2)) + 0.05 * rng.random((K, A))
            P /= P.sum(1, keepdims=True)
            e = np.full(K, 0.5)
            prev = -np.inf
            ll = -np.inf
            for it in range(iters):
                Cp = np.full((K, A), 1e-3)
                Ce = np.full(K, 1e-3)
                Cs = np.full(K, 1e-3)
                ll = 0.0
                for L, (ids, U) in groups.items():
                    w = wts[ids]
                    tot, post_e, post_s = _em_batch(P, e, U, w)
                    ll += float((w * np.log(np.maximum(tot, 1e-300))).sum())
                    Ce += post_e.sum((1, 2))
                    Cs += post_s
                    for k in range(K):
                        np.add.at(Cp[k], U.ravel(), post_e[k].ravel())
                P = Cp / Cp.sum(1, keepdims=True)
                e = Ce / (Ce + Cs)
                if abs(ll - prev) < tol * abs(ll):
                    prev = ll
                    break
                prev = ll
            if best is None or ll > best[0]:
                best = (ll, P.copy(), e.copy(), it + 1)
        self.loglik_train, self.P, self.e, self.iterations = best[0] / LOG2, best[1], best[2], best[3]
        self.train_weight = float(wsum)
        return self

    # ---- scoring
    def _smoothed(self, floor: float | None = None):
        fl = self.floor if floor is None else floor
        A = len(self.units)
        P = (1 - fl) * self.P + fl / (A + 1)
        e = np.clip(self.e, 1e-4, 1 - 1e-4)
        # the extra column is the unknown-unit probability (shared by all slots)
        P = np.concatenate([P, np.full((self.K, 1), fl / (A + 1))], axis=1)
        return P, e

    def logprob2(self, words: Sequence[tuple], floor: float | None = None) -> np.ndarray:
        """log2 P(word) under the (smoothed) grammar; -inf for words longer than K or empty."""
        P, e = self._smoothed(floor)
        out = np.full(len(words), -np.inf)
        for L, (ids, U) in _group_by_length(words, self.idx).items():
            if L == 0 or L > self.K:
                continue
            tot, _, _ = _em_batch(P, e, U, np.ones(len(ids)), posteriors=False)
            out[ids] = np.log2(np.maximum(tot, 1e-300))
        return out

    def allowed(self) -> np.ndarray:
        """Boolean (K, A+1) table of units each slot may emit after pruning (the 'hard' grammar)."""
        M = np.concatenate([self.P >= self.prune, np.zeros((self.K, 1), bool)], axis=1)
        return M & (self.e[:, None] >= self.min_emit)

    def covered(self, words: Sequence[tuple]) -> np.ndarray:
        """Boolean per word: can the pruned grammar (units with P >= prune per slot) generate it, i.e. is there
        a left-to-right alignment of the units to distinct, increasing slots?"""
        M = self.allowed()
        ok = np.zeros(len(words), dtype=bool)
        for L, (ids, U) in _group_by_length(words, self.idx).items():
            if L == 0 or L > self.K:
                continue
            n = len(ids)
            # f[k][:, j]: first j units generated within the first k slots
            f = np.zeros((n, L + 1), dtype=bool)
            f[:, 0] = True
            for k in range(self.K):
                g = f.copy()
                g[:, 1:] |= f[:, :-1] & M[k][U]
                f = g
            ok[ids] = f[:, L]
        return ok

    def n_params(self, min_expected: float = 1.0) -> int:
        """Free parameters of the pruned model: unit probabilities above ``prune`` in the active slots (emission prob >= ``min_emit``) + one emission prob per active slot."""
        act = self.e >= self.min_emit
        return int((self.P[act] >= self.prune).sum() + act.sum())

    def describe(self, top: int = 6) -> list[dict]:
        rows = []
        for k in range(self.K):
            order = np.argsort(-self.P[k])[:top]
            rows.append({"slot": k + 1, "p_emit": float(self.e[k]), "entropy_bits": float(-(self.P[k] * np.log2(self.P[k] + 1e-12)).sum()),
                         "n_units_ge_prune": int((self.P[k] >= self.prune).sum()),
                         "top_units": " ".join(f"{self.units[i]}:{self.P[k, i]:.2f}" for i in order)})
        return rows


def _em_batch(P: np.ndarray, e: np.ndarray, U: np.ndarray, w: np.ndarray, posteriors: bool = True):
    """Forward (and backward) pass for a batch of words of equal length L.
    Returns (total prob per word, posterior emission mass (K, n, L) weighted by w, posterior skip mass per slot (K,))."""
    K = P.shape[0]
    n, L = U.shape
    em = P * e[:, None]                  # (K, A+) prob that slot k emits unit u
    sk = 1.0 - e
    f = np.zeros((K + 1, n, L + 1))
    f[0, :, 0] = 1.0
    for k in range(K):
        prev = f[k]
        cur = prev * sk[k]
        if L:
            cur[:, 1:] += prev[:, :-1] * em[k][U]
        f[k + 1] = cur
    tot = f[K, :, L]
    if not posteriors:
        return tot, None, None
    b = np.zeros((K + 1, n, L + 1))
    b[K, :, L] = 1.0
    for k in range(K, 0, -1):
        nxt = b[k]
        cur = nxt * sk[k - 1]
        if L:
            cur[:, :-1] += nxt[:, 1:] * em[k - 1][U]
        b[k - 1] = cur
    inv = w / np.maximum(tot, 1e-300)
    post_e = np.zeros((K, n, L))
    post_s = np.zeros(K)
    for k in range(K):
        post_e[k] = f[k][:, :-1] * em[k][U] * b[k + 1][:, 1:] * inv[:, None]
        post_s[k] = (f[k] * sk[k] * b[k + 1] * inv[:, None]).sum()
    return tot, post_e, post_s


# ----------------------------------------------------------------------------- unit n-gram baselines

class UnitNgram:
    """Within-word unit model with word boundaries: order 0 (iid units + end) or order 1 (bigram), add-alpha smoothed."""

    def __init__(self, order: int = 1, alpha: float = 0.05):
        self.order, self.alpha = order, alpha

    def fit(self, counts: dict[tuple, float]):
        self.units = sorted({u for w in counts for u in w}, key=str) + ["$"]
        self.idx = {u: i for i, u in enumerate(self.units)}
        A = len(self.units)
        self.A = A
        self.C = np.zeros((A + 1, A + 1))          # row A = start symbol, last column = unknown unit
        for w, c in counts.items():
            if not w:
                continue
            seq = [A] + [self.idx[u] for u in w] + [self.idx["$"]]
            for a, b in zip(seq, seq[1:]):
                self.C[a, b] += c
        self.unigram = self.C.sum(0)
        self.train_weight = float(sum(counts.values()))
        return self

    def logprob2(self, words: Sequence[tuple], alpha: float | None = None) -> np.ndarray:
        a = self.alpha if alpha is None else alpha
        A = self.A
        if self.order == 0:
            p = (self.unigram[:A] + a) / (self.unigram[:A].sum() + a * (A + 1))
        else:
            rows = (self.C[:, :A] + a) / (self.C[:, :A].sum(1, keepdims=True) + a * (A + 1))
        unk_p0 = a / (self.unigram[:A].sum() + a * (A + 1))
        out = np.zeros(len(words))
        end = self.idx["$"]
        for i, w in enumerate(words):
            seq = [A] + [self.idx.get(u, -1) for u in w] + [end]
            s = 0.0
            for x, y in zip(seq, seq[1:]):
                if self.order == 0:
                    pr = p[y] if y >= 0 else unk_p0
                else:
                    ctx = x if x >= 0 else None
                    if y < 0:
                        pr = a / ((self.C[ctx, :A].sum() if ctx is not None else 0) + a * (A + 1))
                    elif ctx is None:
                        pr = 1.0 / (A + 1)
                    else:
                        pr = rows[ctx, y]
                s += math.log2(pr)
            out[i] = s
        return out

    def n_params(self) -> int:
        if self.order == 0:
            return int((self.unigram[:self.A] > 0).sum())
        return int((self.C[:, :self.A] > 0).sum())

    def seen_bigrams_cover(self, words: Sequence[tuple]) -> np.ndarray:
        """Boolean per word: every (previous unit, unit) pair incl. boundaries was seen in training."""
        A = self.A
        end = self.idx["$"]
        out = np.zeros(len(words), dtype=bool)
        for i, w in enumerate(words):
            seq = [A] + [self.idx.get(u, -1) for u in w] + [end]
            out[i] = all(x >= 0 and y >= 0 and self.C[x, y] > 0 for x, y in zip(seq, seq[1:]))
        return out


# ----------------------------------------------------------------------------- prefix-core-suffix

class AffixModel:
    """Word = prefix + core + suffix. Prefix and suffix come from learned sets (possibly empty); the core is a
    non-empty string scored by a within-core unit bigram model. Hard-EM (Viterbi segmentation of every word type),
    candidate affixes = the most frequent word-initial / word-final unit n-grams (length 1-3) of the training
    types, pruned to those actually used."""

    def __init__(self, max_len: int = 3, n_cand: int = 40, iters: int = 6, alpha: float = 0.05, min_core: int = 1):
        self.max_len, self.n_cand, self.iters, self.alpha, self.min_core = max_len, n_cand, iters, alpha, min_core

    def fit(self, counts: dict[tuple, float]):
        words = [w for w in counts if len(w) >= 1]
        self.core_model = None
        # candidate affixes ranked by *productivity*: how many types are "affix + another type" (stem is itself a word)
        vocab = set(counts)
        pre_c, suf_c = Counter(), Counter()
        for w in words:
            for n in range(1, self.max_len + 1):
                if len(w) > n:
                    if w[n:] in vocab:
                        pre_c[w[:n]] += 1
                    if w[:-n] in vocab:
                        suf_c[w[-n:]] += 1
        self.pre = {(): 1.0}
        self.suf = {(): 1.0}
        for a, c in pre_c.most_common(self.n_cand):
            if c >= 3:
                self.pre[a] = float(c)
        for a, c in suf_c.most_common(self.n_cand):
            if c >= 3:
                self.suf[a] = float(c)
        self.pre[()] = max(self.pre.values())
        self.suf[()] = max(self.suf.values())
        self._normalise()
        splits = {w: (0, len(w)) for w in words}
        # initial cores: all words are their own core -> bigram model on whole words
        self._fit_core({w: counts[w] for w in words}, {w: (w, (), ()) for w in words})
        for _ in range(self.iters):
            seg = {w: self._best_split(w) for w in words}
            pc, sc = Counter(), Counter()
            cores = Counter()
            for w, (core, p, s) in seg.items():
                pc[p] += counts[w]
                sc[s] += counts[w]
                cores[core] += counts[w]
            self.pre = {a: v for a, v in pc.items() if v >= 2 or a == ()}
            self.suf = {a: v for a, v in sc.items() if v >= 2 or a == ()}
            self.pre.setdefault((), 1.0)
            self.suf.setdefault((), 1.0)
            self._normalise(pc, sc)
            self._fit_core(cores, None)
        self.seg = {w: self._best_split(w) for w in words}
        self.train_weight = float(sum(counts.values()))
        return self

    def _normalise(self, pc: Counter | None = None, sc: Counter | None = None):
        def norm(d, c):
            keys = list(d)
            vals = np.array([(c[k] if c is not None and k in c else d[k]) + 0.5 for k in keys], dtype=float)
            vals /= vals.sum()
            return dict(zip(keys, vals))
        self.pre_p = norm(self.pre, pc)
        self.suf_p = norm(self.suf, sc)

    def _fit_core(self, cores: dict, _):
        units = sorted({u for w in cores for u in w}, key=str)
        self.core_units = units
        self.core_idx = {u: i for i, u in enumerate(units)}
        A = len(units)
        C = np.zeros((A + 1, A + 1))
        for w, c in cores.items():
            seq = [A] + [self.core_idx[u] for u in w] + [A]
            for a, b in zip(seq, seq[1:]):
                C[a, b] += c
        self.core_logp = np.log2((C + self.alpha) / (C.sum(1, keepdims=True) + self.alpha * (A + 1)))
        self.core_A = A

    def core_logprob2(self, core: tuple) -> float:
        A = self.core_A
        seq = [A] + [self.core_idx.get(u, -1) for u in core] + [A]
        s = 0.0
        for a, b in zip(seq, seq[1:]):
            if a < 0 or b < 0:
                s += math.log2(1.0 / (A + 1)) - 4.0          # unseen unit: heavy penalty
            else:
                s += self.core_logp[a, b]
        return s

    def _best_split(self, w: tuple):
        best = None
        n = len(w)
        for pl in range(0, min(self.max_len, n - self.min_core) + 1):
            p = w[:pl]
            if p not in self.pre_p:
                continue
            for sl in range(0, min(self.max_len, n - pl - self.min_core) + 1):
                s = w[n - sl:] if sl else ()
                if s not in self.suf_p:
                    continue
                core = w[pl:n - sl]
                sc = math.log2(self.pre_p[p]) + math.log2(self.suf_p[s]) + self.core_logprob2(core)
                if best is None or sc > best[0]:
                    best = (sc, core, p, s)
        if best is None:
            core = w
            return core, (), ()
        return best[1], best[2], best[3]

    def logprob2(self, words: Sequence[tuple]) -> np.ndarray:
        """log2 P of the best split (Viterbi approximation to the sum over splits)."""
        out = np.zeros(len(words))
        for i, w in enumerate(words):
            if not w:
                out[i] = -np.inf
                continue
            best = -np.inf
            n = len(w)
            for pl in range(0, min(self.max_len, n - self.min_core) + 1):
                p = w[:pl]
                pp = self.pre_p.get(p)
                if pp is None:
                    continue
                for sl in range(0, min(self.max_len, n - pl - self.min_core) + 1):
                    s = w[n - sl:] if sl else ()
                    sp = self.suf_p.get(s)
                    if sp is None:
                        continue
                    sc = math.log2(pp) + math.log2(sp) + self.core_logprob2(w[pl:n - sl])
                    best = max(best, sc)
            if best == -np.inf:
                best = math.log2(1e-3) + self.core_logprob2(w) + math.log2(1e-3)
            out[i] = best
        return out

    def n_params(self) -> int:
        return len(self.pre_p) + len(self.suf_p) + int((self.core_logp > -30).sum())

    def stats(self, counts: dict[tuple, float]) -> dict:
        n_types = len(self.seg)
        tok = sum(counts[w] for w in self.seg)
        has_pre = sum(1 for w, (c, p, s) in self.seg.items() if p)
        has_suf = sum(1 for w, (c, p, s) in self.seg.items() if s)
        has_pre_t = sum(counts[w] for w, (c, p, s) in self.seg.items() if p)
        has_suf_t = sum(counts[w] for w, (c, p, s) in self.seg.items() if s)
        cores = {c for c, p, s in self.seg.values()}
        return {"n_prefixes": len([a for a in self.pre_p if a]), "n_suffixes": len([a for a in self.suf_p if a]),
                "prefix_type_share": has_pre / n_types, "suffix_type_share": has_suf / n_types,
                "prefix_token_share": has_pre_t / tok, "suffix_token_share": has_suf_t / tok,
                "cores_per_type": len(cores) / n_types}

    def top_affixes(self, k: int = 12) -> tuple[list, list]:
        pre = sorted(((a, p) for a, p in self.pre_p.items() if a), key=lambda x: -x[1])[:k]
        suf = sorted(((a, p) for a, p in self.suf_p.items() if a), key=lambda x: -x[1])[:k]
        return pre, suf
